{
  "name": "通量可调超导量子比特",
  "name_en": "Flux-tunable superconducting qubit",
  "manufacturer": "",
  "description": "一种工作于低温量子测量系统中的超导量子比特，可通过微波信号进行驱动与读出，并通过磁通偏置调谐到甜点或反甜点附近。该器件常用于连续波谱测、时域相干实验、磁通扫描、自动表征以及量子读出链优化。",
  "description_en": "A superconducting qubit used in low-temperature quantum measurement systems. It is controlled and read out with microwave signals and can be tuned with magnetic flux bias near sweet spots or anti-sweet spots. It is commonly used for continuous-wave spectroscopy, time-domain coherence experiments, flux tuning, automated characterization, and optimization of the qubit readout chain.",
  "tag_hints": [
    "superconducting qubit",
    "flux-tunable transmon",
    "circuit QED readout",
    "microwave spectroscopy",
    "time-domain qubit control",
    "flux bias tuning",
    "sweet spot operation",
    "TWPA pump cancellation"
  ],
  "actions": [
    {
      "action_name": "auto-prepare_for_continuous_wave",
      "description": "准备量子比特用于连续波谱测，并配置适合相位与角度检测的读出通道。",
      "description_en": "Prepare the qubit for continuous-wave spectroscopy and configure the readout channels for phase and angle-based detection."
    },
    {
      "action_name": "auto-prepare_readout",
      "description": "配置量子比特读出，设置读出频率与微波源，并生成读出脉冲。",
      "description_en": "Configure qubit readout by setting the readout frequencies and microwave sources and generating the readout pulse."
    },
    {
      "action_name": "auto-prepare_for_timedomain",
      "description": "准备量子比特用于时域实验。",
      "description_en": "Prepare the qubit for time-domain experiments."
    },
    {
      "action_name": "auto-prepare_for_fluxing",
      "description": "准备量子比特进行磁通偏置或磁通脉冲实验。",
      "description_en": "Prepare the qubit for flux-bias tuning or flux-pulse experiments."
    },
    {
      "action_name": "auto-prepare_characterizing",
      "description": "准备量子比特进行自动表征，并将相关其他量子比特停放到合适的偏置点。",
      "description_en": "Prepare the qubit for automated characterization and park the other relevant qubits at suitable bias points."
    },
    {
      "action_name": "auto-hal_acq_spec_mode_on",
      "description": "打开用于谱测的采集模式。",
      "description_en": "Enable the acquisition mode used for spectroscopy."
    },
    {
      "action_name": "auto-hal_acq_spec_mode_off",
      "description": "关闭用于谱测的采集模式。",
      "description_en": "Disable the acquisition mode used for spectroscopy."
    },
    {
      "action_name": "auto-hal_spec_source_on",
      "description": "以设定功率打开量子比特谱测微波源，可选择脉冲方式。",
      "description_en": "Turn on the spectroscopy microwave source for the qubit at the specified power, optionally in pulsed mode."
    },
    {
      "action_name": "auto-hal_spec_source_off",
      "description": "关闭量子比特谱测微波源。",
      "description_en": "Turn off the spectroscopy microwave source for the qubit."
    },
    {
      "action_name": "auto-hal_flux_get_parameters",
      "description": "获取量子比特磁通控制通道的参数。",
      "description_en": "Get the parameters of the qubit flux-control channel."
    },
    {
      "action_name": "auto-get_int_avg_det",
      "description": "配置积分平均读出检测，用于量子比特信号的积分与平均测量。",
      "description_en": "Configure integrated-averaging readout detection for integrating and averaging the qubit measurement signal."
    },
    {
      "action_name": "auto-prepare_PPC",
      "description": "初始化参数泵浦控制器，用于TWPA泵浦音调及其抵消音调的产生。",
      "description_en": "Initialize the parametric pump controller for generating TWPA pump tones and their cancellation tones."
    }
  ]
}

